-- Synthetic identities only; runs in an isolated fresh PG17 container.
SET ROLE mass_core_admin;
INSERT INTO mass_core.assessment_definitions(period_id) SELECT q.id FROM mass_core.assessment_periods q WHERE q.academic_year_id='20000000-0000-4000-8000-000000000001' AND NOT EXISTS(SELECT 1 FROM mass_core.assessment_definitions d WHERE d.period_id=q.id);
INSERT INTO mass_core.programme_cohorts(id,label,academic_year_id) VALUES('23000000-0000-4000-8000-000000000024','Synthetic reviewed Grade5 cohort','20000000-0000-4000-8000-000000000001');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',false);
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-29','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')->>'children')::int>=0,'reviewed read accepts only readable scope');
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000002']::uuid[],'2026-10-29','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'42501','reviewed aggregate rejects another centre');
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(NULL,'2026-10-29','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'42501','reviewed aggregate rejects global null scope');
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-29','2026-10-02','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'22023','reviewed aggregate rejects noncalendar periods');
SELECT core_test.assert_true(NOT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-29','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')::text LIKE '%Synthetic record%','aggregate does not expose profile names');
INSERT INTO core_test.ids SELECT 'R1',child_id,enrolment_id FROM mass_api.register_student_once('60000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','5','Morning','2026-04-01','Synthetic reviewed learner one','Girl');
INSERT INTO core_test.ids SELECT 'R2',child_id,enrolment_id FROM mass_api.register_student_once('60000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','5','Morning','2026-04-01','Synthetic reviewed learner two',NULL);
SELECT mass_api.close_enrolment(core_test.id('R1'),1,'2026-07-01','Left programme');
INSERT INTO core_test.ids SELECT 'R1new',child_id,mass_api.add_enrolment(child_id,'10000000-0000-4000-8000-000000000001','6','Morning','2026-07-01','Active') FROM core_test.ids WHERE label='R1';
SELECT mass_api.record_assessment(core_test.id('R1'),(SELECT d.id FROM mass_core.assessment_definitions d JOIN mass_core.assessment_periods q ON q.id=d.period_id WHERE q.academic_year_id='20000000-0000-4000-8000-000000000001' AND q.quarter=1),NULL,0,0);
SELECT mass_api.record_assessment(core_test.id('R1new'),(SELECT d.id FROM mass_core.assessment_definitions d JOIN mass_core.assessment_periods q ON q.id=d.period_id WHERE q.academic_year_id='20000000-0000-4000-8000-000000000001' AND q.quarter=2),'2026-09-01',10,0);
SELECT mass_api.record_morarji(mass_api.add_morarji_member(core_test.id('R1'),'23000000-0000-4000-8000-000000000024'),true,true,true,'Synthetic source-backed school',0);
SELECT mass_api.add_morarji_member(core_test.id('R2'),'23000000-0000-4000-8000-000000000024');
SELECT mass_api.record_activity_detail('71000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Morning','2026-10-03','Synthetic sport one','Sports','Held',0);
SELECT mass_api.record_activity_detail('71000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','Morning','2026-10-10','Synthetic sport two','Sports','Held',0);
SELECT mass_api.record_activity_detail('71000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','Morning','2026-10-17','Synthetic cultural','Cultural','Held',0);
SELECT mass_api.record_activity_detail('71000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','Morning','2026-10-24','Synthetic unclassified',NULL,'Held',0);
SELECT mass_api.record_participation(core_test.id('R1new'),'71000000-0000-4000-8000-000000000001',true,0);
SELECT mass_api.record_participation(core_test.id('R1new'),'71000000-0000-4000-8000-000000000002',true,0);
SELECT mass_api.record_participation(core_test.id('R1new'),'71000000-0000-4000-8000-000000000003',true,0);
SELECT mass_api.record_participation(core_test.id('R2'),'71000000-0000-4000-8000-000000000001',false,0);
SELECT mass_api.record_participation(core_test.id('R2'),'71000000-0000-4000-8000-000000000004',true,0);
DO $$DECLARE d date;BEGIN FOR d IN SELECT generate_series('2026-10-01'::date,'2026-10-31'::date,interval '1 day')::date LOOP
 PERFORM mass_api.record_calendar('10000000-0000-4000-8000-000000000001','Morning',d,true,'62000000-0000-4000-8000-000000000001');
 PERFORM mass_api.record_attendance(core_test.id('R2'),d,'P',0);
 PERFORM mass_api.record_attendance(core_test.id('R1new'),d,CASE WHEN extract(day FROM d)<=15 THEN 'P' ELSE 'A' END,0);
END LOOP;END;$$;
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001',NULL,'Morning')->'activity'->>'participants')::int=2,'monthly participants count children once across repeated events');
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001',NULL,'Morning')->'activity'->'categories'->>'Sports')::int=1,'category participation deduplicates repeated sports events');
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001',NULL,'Morning')->'bands'->'counts'->>'above25')::int=1,'above25 present days remain outside21–25 band');
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001',NULL,NULL,'Unknown')->>'children')::int>=1,'Unknown gender filter is explicit and does not expose profiles');
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'42501','mixed readable/unreadable scope denied atomically');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000007"}',false);
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'42501','expired scope cannot read reviewed aggregates');
RESET ROLE;
SET ROLE anon;
SELECT core_test.expect_error($q$SELECT mass_api.reviewed_chart_metrics(ARRAY['10000000-0000-4000-8000-000000000001']::uuid[],'2026-10-31','2026-10-01','2026-11-01','20000000-0000-4000-8000-000000000001')$q$,'42501','anonymous reviewed reporting denied');
RESET ROLE;
SELECT core_test.assert_true((SELECT proconfig=ARRAY['search_path=pg_catalog'] AND pg_get_userbyid(proowner)='mass_core_owner' AND prosecdef FROM pg_proc WHERE oid='mass_api.reviewed_chart_metrics(uuid[],date,date,date,uuid,text,text,text,integer,integer)'::regprocedure),'reviewed aggregate fixed owner/search path');
SELECT core_test.assert_true(NOT has_function_privilege('anon','mass_api.reviewed_chart_metrics(uuid[],date,date,date,uuid,text,text,text,integer,integer)','EXECUTE') AND NOT has_function_privilege('service_role','mass_api.reviewed_chart_metrics(uuid[],date,date,date,uuid,text,text,text,integer,integer)','EXECUTE'),'reviewed aggregate least-privilege ACL');
